    /**
     * Method to retrieve the PrivacyNotice via an PrivacyNoticePrimaryKey.
     * @param 	id Long
     * @return 	PrivacyNotice
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public PrivacyNotice handle( FindPrivacyNoticeQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPrivacyNoticeId() );
    }
    
    /**
     * Method to retrieve a collection of all PrivacyNotices
     *
     * @param	query	FindAllPrivacyNoticeQuery 
     * @return 	List<PrivacyNotice> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<PrivacyNotice> handle( FindAllPrivacyNoticeQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPrivacyNotice,
 * but only if the id matches
 *
 * @param		entity	PrivacyNotice
 */
	protected void emitFindPrivacyNotice( PrivacyNotice entity ) {
		LOGGER.info("handling emitFindPrivacyNotice" );
		
	    queryUpdateEmitter.emit(FindPrivacyNoticeQuery.class,
	                            query -> query.getFilter().getPrivacyNoticeId().equals(entity.getPrivacyNoticeId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPrivacyNotice
	 * 
	 * @param		entity	PrivacyNotice
	 */
	protected void emitFindAllPrivacyNotice( PrivacyNotice entity ) {
		LOGGER.info("handling emitFindAllPrivacyNotice" );
		
	    queryUpdateEmitter.emit(FindAllPrivacyNoticeQuery.class,
	                            query -> true,
	                            entity);
	}

